-- Seed real KMUTT vendor + menu data (16 stalls, 500 menu items)
-- Source: menu_items 1.csv (student-provided, real on-campus vendors)

-- 1. Insert the 16 vendors, skipping any that already exist by name.
WITH v(name) AS (
  VALUES
  ('Dino Papa'),
  ('Fahsai Restaurant'),
  ('Loong Noom Square'),
  ('Uncle Chicky'),
  ('P'' Pom'),
  ('Krua Thai'),
  ('P'' Mee'),
  ('Pa Kaew'),
  ('Som Tum'),
  ('Mae Nong Punch'),
  ('Dormitory Drinks'),
  ('Mr.Mouslache'),
  ('Sai Nua Kitchen'),
  ('Jirapan Drinks'),
  ('Nui Noodles'),
  ('Thanaporn Fresh Milk')
)
INSERT INTO vendors (name, is_open)
SELECT v.name, true
FROM v
WHERE NOT EXISTS (SELECT 1 FROM vendors WHERE vendors.name = v.name);

-- 2. Insert the menu items, resolving vendor_id by vendor name.
